27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    private String telephone;
49	
50	    @Column(name = "email")
51	    private String email;
52	
53	    @Column(name = "postcode")
54	    private String postcode;
55	
56	    @Column(name = "birth_date")
57	    private LocalDate birthDate;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @Column(name = "possible_duplicate")
69	    private Boolean possibleDuplicate;
70	
71	    @Column(name = "possible_duplicate_of")
72	    private Integer possibleDuplicateOf;
73	
74	    @Column(name = "household_gold")
75	    private Boolean householdGold;
76	
77	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
78	    private Set<Pet> pets;
79	
80	    public String getEmail() {
81	        return this.email;
82	    }
83	
84	    public void setEmail(String email) {
85	        this.email = email == null ? null : email.toLowerCase(Locale.ENGLISH);
86	    }
87	
88	    public String getAddress() {
89	        return this.address;
90	    }
91	
92	    public void setAddress(String address) {
93	        this.address = AddressNormalizer.normalize(address);
94	    }
95	
96	    public String getPostcode() {
97	        return this.postcode;
98	    }
99	
100	    public void setPostcode(String postcode) {
101	        this.postcode = postcode;
102	    }
103	
104	    public String getCity() {
105	        return this.city;
106	    }
107	
108	    public void setCity(String city) {
109	        this.city = city;
110	    }
111	
112	    public String getTelephone() {
113	        return this.telephone;
114	    }
115	
116	    public void setTelephone(String telephone) {
117	        this.telephone = E164.toE164(telephone);
118	    }
119	
120	    public LocalDate getBirthDate() {
121	        return this.birthDate;
122	    }
123	
124	    public void setBirthDate(LocalDate birthDate) {
125	        this.birthDate = birthDate;
126	    }
127	
128	    public LocalDate getRegistrationDate() {
129	        return this.registrationDate;
130	    }
131	
132	    public void setRegistrationDate(LocalDate registrationDate) {
133	        this.registrationDate = registrationDate;
134	    }
135	
136	    public String getCustomerCode() {
137	        return this.customerCode;
138	    }
139	
140	    public void setCustomerCode(String customerCode) {
141	        this.customerCode = customerCode;
142	    }
143	
144	    public Integer getNamesakeCount() {
145	        return this.namesakeCount;
146	    }
147	
148	    public void setNamesakeCount(Integer namesakeCount) {
149	        this.namesakeCount = namesakeCount;
150	    }
151	
152	    public Boolean getPossibleDuplicate() {
153	        return this.possibleDuplicate;
154	    }
155	
156	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
157	        this.possibleDuplicate = possibleDuplicate;
158	    }
159	
160	    public Integer getPossibleDuplicateOf() {
161	        return this.possibleDuplicateOf;
162	    }
163	
164	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
165	        this.possibleDuplicateOf = possibleDuplicateOf;
166	    }
167	
168	    public Boolean getHouseholdGold() {
169	        return this.householdGold;
170	    }
171	
172	    public void setHouseholdGold(Boolean householdGold) {
173	        this.householdGold = householdGold;
174	    }
175	
176	    protected Set<Pet> getPetsInternal() {
177	        if (this.pets == null) {
178	            this.pets = new HashSet<>();
179	        }
180	        return this.pets;
181	    }
182	
183	    protected void setPetsInternal(Set<Pet> pets) {
184	        this.pets = pets;
185	    }
186	
187	    public List<Pet> getPets() {
188	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
189	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
190	        return Collections.unmodifiableList(sortedPets);
191	    }
192	
193	    public void setPets(List<Pet> pets) {
194	        this.pets = new HashSet<>(pets);
195	    }
196	
197	    public void addPet(Pet pet) {
198	        getPetsInternal().add(pet);
199	        pet.setOwner(this);
200	    }
201	
202	    /**
203	     * Return the Pet with the given name, or null if none found for this Owner.
204	     *
205	     * @param name to test
206	     * @return true if pet name is already in use
207	     */
208	    public Pet getPet(String name) {
209	        return getPet(name, false);
210	    }
211	
212	    /**
213	     * Return the Pet with the given name, or null if none found for this Owner.
214	     *
215	     * @param name to test
216	     * @return true if pet name is already in use
217	     */
218	    public Pet getPet(String name, boolean ignoreNew) {
219	        name = name.toLowerCase();
220	        for (Pet pet : getPetsInternal()) {
221	            if (!ignoreNew || !pet.isNew()) {
222	                String compName = pet.getName();
223	                compName = compName.toLowerCase();
224	                if (compName.equals(name)) {
225	                    return pet;
226	                }
227	            }
228	        }
229	        return null;
230	    }
231	
232	    public Pet getPet(Integer petId) {
233	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
234	    }
235	
236	    @Override
237	    public String toString() {
238	        return new ToStringCreator(this)
239	
240	            .append("id", this.getId())
241	            .append("new", this.isNew())
242	            .append("lastName", this.getLastName())
243	            .append("firstName", this.getFirstName())
244	            .append("address", this.address)
245	            .append("city", this.city)
246	            .append("telephone", this.telephone)
247	            .toString();
248	    }
249	}
