17	    /** Record on {@code candidate} whether it possibly duplicates an existing owner (same last
18	     *  name and postcode, different telephone) and, if so, that owner's id. A declared household
19	     *  member ({@code sharesHousehold}) is never a suspected duplicate. */
20	    public static void assign(Owner candidate, boolean sharesHousehold, Collection<Owner> existing) {
21	        Integer match = sharesHousehold ? null : matchId(candidate, existing);
22	        candidate.setPossibleDuplicate(match != null);
23	        candidate.setPossibleDuplicateOf(match);
24	    }
