27	        for (Owner other : existing) {
28	            if (candidate.getPostcode() != null
29	                && candidate.getPostcode().equals(other.getPostcode())
30	                && candidate.getLastName().equalsIgnoreCase(other.getLastName())
31	                && !digits(candidate.getTelephone()).equals(digits(other.getTelephone()))) {
