6	/**
7	 * Rejects owner emails whose domain belongs to a known disposable-email provider.
8	 * The blocklist is fixed: {@code mailinator.com}, {@code tempmail.com} and
9	 * {@code guerrillamail.com}. An absent or domain-less email is never blocked.
10	 */
11	public final class DisposableEmail {
12	
13	    /** Lower-case domains that are not accepted for an owner's email. */
14	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
15	        "mailinator.com", "tempmail.com", "guerrillamail.com");
16	
17	    private DisposableEmail() {
18	    }
19	
20	    /**
21	     * True when {@code email} has a domain (the part after the last {@code @}) that is on
22	     * the disposable-domain blocklist. Comparison ignores case; a null or {@code @}-less
23	     * value returns {@code false}.
24	     */
25	    public static boolean isBlocked(String email) {
26	        if (email == null) {
27	            return false;
28	        }
29	        int at = email.lastIndexOf('@');
30	        if (at < 0) {
31	            return false;
32	        }
33	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
34	        return BLOCKED_DOMAINS.contains(domain);
35	    }
36	}
