18	
19	import java.util.Map;
20	import java.util.regex.Pattern;
21	
22	/**
23	 * Converts free-form telephone input into E.164 form: keep a leading '+' and country
24	 * code when present, otherwise assume '+61' and drop a single leading '0' from the
25	 * national digits. Spaces, dashes and brackets are stripped and 8 to 15 digits must
26	 * remain after the '+', or an {@link InvalidTelephoneException} is thrown.
27	 */
28	public final class E164 {
29	
30	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
31	
32	    private static final Pattern EIGHT_TO_FIFTEEN_DIGITS = Pattern.compile("\\d{8,15}");
33	
34	    /** Country calling code -> required national-number length. */
35	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
36	
37	    private E164() {
38	    }
39	
40	    /** True unless the digits carry a known country code with the wrong national-number length. */
41	    private static boolean nationalLengthValid(String digits) {
42	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTHS.entrySet()) {
43	            if (digits.startsWith(country.getKey())) {
44	                return digits.length() - country.getKey().length() == country.getValue();
45	            }
46	        }
47	        return true;
48	    }
49	
50	    public static String toE164(String raw) {
51	        if (raw == null) {
52	            throw new InvalidTelephoneException(null);
53	        }
54	        String trimmed = raw.trim();
55	        boolean explicit = trimmed.startsWith("+");
56	        String digits = SEPARATORS.matcher(explicit ? trimmed.substring(1) : trimmed).replaceAll("");
57	        if (!explicit) {
58	            if (digits.startsWith("0")) {
59	                digits = digits.substring(1);
60	            }
61	            digits = "61" + digits;
62	        }
63	        if (!EIGHT_TO_FIFTEEN_DIGITS.matcher(digits).matches() || !nationalLengthValid(digits)) {
64	            throw new InvalidTelephoneException(raw);
65	        }
66	        return "+" + digits;
67	    }
68	}
