2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Rolls a date forward onto a business day: a Saturday or Sunday advances to the
8	 * following Monday, while a weekday is returned unchanged.
9	 */
10	public final class BusinessDay {
11	
12	    private BusinessDay() {
13	    }
14	
15	    /** {@code date} unchanged when it is a weekday, otherwise the following Monday. */
16	    public static LocalDate rollForward(LocalDate date) {
17	        DayOfWeek day = date.getDayOfWeek();
18	        if (day == DayOfWeek.SATURDAY) {
19	            return date.plusDays(2);
20	        }
21	        if (day == DayOfWeek.SUNDAY) {
22	            return date.plusDays(1);
23	        }
24	        return date;
25	    }
26	}
