24	/**
25	 * Signals that the maximum number of owners registrable in a single day has been reached.
26	 * Mapped to HTTP 429 Too Many Requests by {@link ExceptionControllerAdvice}.
27	 */
28	public class DailyOwnerLimitException extends RuntimeException {
29	
30	    /** Maximum owners registrable per day; once this many share today's date the next is rejected. */
31	    private static final int DAILY_LIMIT = 100;
32	
33	    public DailyOwnerLimitException() {
34	        super("Daily owner registration limit reached: " + DAILY_LIMIT);
35	    }
36	
37	    /**
38	     * Throw if {@code existingOwners} already contains {@value #DAILY_LIMIT} or more owners
39	     * whose registration date is today.
40	     */
41	    public static void rejectIfAtLimit(Collection<Owner> existingOwners) {
42	        LocalDate today = org.springframework.samples.petclinic.util.BusinessDay.rollForward(LocalDate.now());
43	        long count = existingOwners.stream()
44	            .filter(owner -> today.equals(owner.getRegistrationDate()))
45	            .count();
46	        if (count >= DAILY_LIMIT) {
47	            throw new DailyOwnerLimitException();
48	        }
49	    }
50	}
