18	
19	import java.util.Collection;
20	import java.util.Locale;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	
24	/**
25	 * Signals that a new owner's city already holds the maximum number of owners.
26	 * Mapped to HTTP 409 Conflict by {@link ExceptionControllerAdvice}.
27	 */
28	public class CityAtCapacityException extends RuntimeException {
29	
30	    /** Maximum owners allowed per city; the next owner in a full city is rejected. */
31	    private static final int CITY_CAPACITY = 50;
32	
33	    public CityAtCapacityException(String city) {
34	        super("City already at capacity: " + city);
35	    }
36	
37	    /** Canonicalize a city so comparison ignores case and collapses whitespace runs. */
38	    private static String normalize(String value) {
39	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
40	    }
41	
42	    /**
43	     * Throw if {@code existingOwners} already contains {@value #CITY_CAPACITY} or more owners
44	     * whose normalized city matches {@code city}.
45	     */
46	    public static void rejectIfAtCapacity(String city, Collection<Owner> existingOwners) {
47	        String candidate = normalize(city);
48	        long count = existingOwners.stream()
49	            .filter(owner -> candidate.equals(normalize(owner.getCity())))
50	            .count();
51	        if (count >= CITY_CAPACITY) {
52	            throw new CityAtCapacityException(city);
53	        }
54	    }
55	}
