25	 * Mapped to HTTP 409 Conflict by {@link ExceptionControllerAdvice}.
26	 */
27	public class DuplicateTelephoneException extends RuntimeException {
28	
29	    public DuplicateTelephoneException(String telephone) {
30	        super("Telephone already in use: " + telephone);
31	    }
32	
33	    /** Reduce a telephone to its digits only, so equality ignores formatting differences. */
34	    private static String normalize(String telephone) {
35	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
