24	/**
25	 * Signals that a new owner's lower-cased email is already used by an existing owner.
26	 * Mapped to HTTP 409 Conflict by {@link ExceptionControllerAdvice}.
27	 */
28	public class DuplicateEmailException extends RuntimeException {
29	
30	    public DuplicateEmailException(String email) {
31	        super("Email already in use: " + email);
32	    }
33	
34	    /** Lower-case an email so equality ignores case; blank/absent emails never match. */
35	    private static String normalize(String email) {
36	        return email == null ? "" : email.trim().toLowerCase(Locale.ROOT);
37	    }
38	
39	    /**
40	     * Throw if {@code email} lower-cases to the same value as the email of any owner in
41	     * {@code existingOwners}. A blank candidate email is treated as absent and never rejected.
42	     */
43	    public static void rejectIfDuplicate(String email, Collection<Owner> existingOwners) {
44	        String candidate = normalize(email);
45	        if (candidate.isEmpty()) {
46	            return;
47	        }
48	        for (Owner owner : existingOwners) {
49	            if (candidate.equals(normalize(owner.getEmail()))) {
50	                throw new DuplicateEmailException(email);
51	            }
52	        }
53	    }
